item.aggregated_output:
    careers: strings(source.careers),
    industries: strings(source.industries),
    company_sizes: strings(source.company_sizes),
    regions: strings(source.regions),
    tools_any: strings(source.tools_any),
    require_work: source.require_work !== false,
  }
}

function text(raw: unknown, max: number): string {
  if (typeof raw !== 'string') return ''
  // eslint-disable-next-line no-control-regex
  return raw.replace(/\r\n?/g, '\n').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '').trim().slice(0, max)
}

function parseOptions(raw: unknown, path: string, errors: FieldErrors): (ChoiceOption & { disqualify: boolean })[] {
  const out: (ChoiceOption & { disqualify: boolean })[] = []
  list(raw).forEach((entry, index) => {
    const o = (typeof entry === 'object' && entry !== null ? entry : {}) as Record<string, unknown>
    const label = text(o.label, 120)
    if (!label) return
    const id = typeof o.id === 'string' && ID.test(o.id) && !out.some((x) => x.id === o.id) ? o.id : `o${index + 1}`
    out.push({ id: out.some((x) => x.id === id) ? `o${index + 1}x` : id, label, disqualify: o.disqualify === true })
  })
  if (out.length > 12) errors[path] = '선택지는 12개까지예요.'
  return out.slice(0, 12)
      : []
    if ((kind === 'choice' || kind === 'multi') && options.length < 2) errors[path] = '선택지를 2개 이상 넣어 주세요.'
    out.push({ id, text: questionText, kind, options, required: q.required !== false })
  })
  if (Object.keys(errors).length > 0) throw invalid(errors)
  return out
}

export function readForm(raw: unknown): FormQuestion[] {
  return list(raw).filter((q): q is FormQuestion =>
    typeof q === 'object' && q !== null && typeof (q as FormQuestion).id === 'string')
}

export function isWebLink(raw: string): boolean {
  try {
    const url = new URL(raw)
    return (url.protocol === 'https:' || url.protocol === 'http:') && raw.length <= 500
  } catch {
    return false
  }
}

export function parseLinks(raw: unknown): TaskLink[] {
  const errors: FieldErrors = {}
  const out: TaskLink[] = []
  list(raw).slice(0, 8).forEach((entry, index) => {
    const l = (typeof entry === 'object' && entry !== null ? entry : {}) as Record<string, unknown>
    const url = text(l.url, 500)
    if (!url) return
    if (!isWebLink(url)) {
      errors[`task_links[${index}]`] = 'http(s)로 시작하는 주소만 넣을 수 있어요.'
      return
    }
    out.push({ label: text(l.label, 60) || '링크', url })
  })
  if (Object.keys(errors).length > 0) throw invalid(errors)
  return out
}

