/** The key the dev server derives when none is configured (env.ts resolveKey). */
function devKey(purpose) {
  const seed = `insight-development-key-do-not-use-in-production:${purpose}`
  const out = Buffer.alloc(32)
  for (let i = 0; i < 32; i++) out[i] = seed.charCodeAt(i % seed.length) ^ (i * 31)
  return out
}

async function envKey(variable, purpose) {
  if (process.env[variable]) return Buffer.from(process.env[variable], 'hex')
  try {
    const text = await readFile(new URL('../.env.dev', import.meta.url), 'utf8')
    const found = new RegExp(`^${variable}=(.+)$`, 'm').exec(text)?.[1]?.trim()
    if (found) return Buffer.from(found, 'hex')
  } catch {
    // fall through
  }
  return devKey(purpose)
}

