async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const request = toRequest(req)
  const url = new URL(request.url)

  // The sitemap is drawn by the application, like the API (routes/meta.ts).
  const isApi = url.pathname.startsWith('/api/') || url.pathname === '/sitemap.xml'

  const meter: Meter = { statements: 0, sentAt: [], started: Date.now() }
  const response = isApi
    ? await meters.run(meter, () => app.fetch(request))
    : request.method === 'GET' || request.method === 'HEAD'
      ? await staticFiles.serve(request, url.pathname)
      : new Response(JSON.stringify({ error: { code: 'not_found', message: '요청한 경로가 없습니다.' } }), {
          status: 404,
          headers: { 'content-type': 'application/json; charset=utf-8' },
        })

  // A route may answer without reading the body: an early 401, a 413, or an
  // idempotent replay that already knows the result. Those bytes are still in
  // the socket, and leaving them there poisons the connection - the next
  // request on it is reset. Draining has to go through the same web stream the
  // request was built from, because converting the Node stream handed it over.
  if (serverTiming && isApi) {
    response.headers.append(
      'server-timing',
      `app;dur=${Date.now() - meter.started}, db;desc="${meter.statements} statements @ ${meter.sentAt.join(' ')}"`,
    )
  }
  const drained = await drainBody(request)
  if (!drained) {
    // Too large to discard: let Node close the connection rather than hand a
    // half-read socket to the next request.
    response.headers.set('connection', 'close')
  }
  await writeResponse(res, response)
}

/** Largest unread body we will discard to keep a connection reusable. */
const MAX_DRAIN_BYTES = 8 * 1024 * 1024

async function drainBody(request: Request): Promise<boolean> {
  const body = request.body
  if (!body || request.bodyUsed) return true
  const reader = body.getReader()
  let seen = 0
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) return true
      seen += value?.byteLength ?? 0
      if (seen > MAX_DRAIN_BYTES) {
        await reader.cancel().catch(() => undefined)
        return false
      }
    }
  } catch {
    return false
  }
}

/**
 * Whether a reverse proxy in front of this server sets the client address.
 *
 * Only when the operator says so (INSIGHT_TRUST_PROXY=true). Otherwise these
 * headers come from the client itself, and believing them let anyone pick
 * the address the sign-in and sign-up limits count against - a fresh one per
 * attempt. A proxy that is trusted must overwrite X-Real-IP; the first entry
 * of X-Forwarded-For is whatever the client put there.
 */
const behindProxy = ['1', 'true', 'yes', 'on'].includes(
  (process.env.INSIGHT_TRUST_PROXY ?? '').trim().toLowerCase(),
)
const CLIENT_ADDRESS_HEADERS = new Set(['cf-connecting-ip', 'x-real-ip', 'x-forwarded-for', 'true-client-ip'])

function toRequest(req: IncomingMessage): Request {
  const forwardedProto = (req.headers['x-forwarded-proto'] as string | undefined)?.split(',')[0]?.trim()
  const proto = forwardedProto || 'http'
  const host = (req.headers.host ?? `localhost:${port}`).toString()
  const url = `${proto}://${host}${req.url ?? '/'}`

  const headers = new Headers()
  for (const [key, value] of Object.entries(req.headers)) {
    if (value === undefined) continue
    if (!behindProxy && CLIENT_ADDRESS_HEADERS.has(key.toLowerCase())) continue
    if (Array.isArray(value)) for (const entry of value) headers.append(key, entry)
    else headers.set(key, value)
  }
  // Without a proxy in front, the only address worth believing is the
  // socket's. Anything the client sent saying otherwise was dropped above.
  if (!behindProxy && req.socket.remoteAddress) headers.set('x-real-ip', req.socket.remoteAddress)

  const method = (req.method ?? 'GET').toUpperCase()
  const hasBody = method !== 'GET' && method !== 'HEAD'
  return new Request(url, {
    method,
    headers,
    body: hasBody ? (Readable.toWeb(req) as ReadableStream) : null,
    // @ts-expect-error Node requires duplex for streaming request bodies
    duplex: hasBody ? 'half' : undefined,
  })
}

async function writeResponse(res: ServerResponse, response: Response): Promise<void> {
  const headers: Record<string, string | string[]> = {}
  for (const [key, value] of response.headers.entries()) {
    if (key.toLowerCase() === 'set-cookie') continue
    headers[key] = value
  }
  const cookies = response.headers.getSetCookie?.() ?? []
  if (cookies.length > 0) headers['set-cookie'] = cookies

  res.writeHead(response.status, headers)
  if (!response.body) {
    res.end()
    return
  }
  const reader = response.body.getReader()
  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      if (value) {
        if (!res.write(value)) {
          await new Promise<void>((resolve) => res.once('drain', resolve))
        }
      }
    }
  } finally {
    res.end()
  }
}

