/**
 * Builds the typed environment, failing fast with an actionable message. In dev
 * mode missing keys are derived from a fixed development seed so `npm run dev`
 * works with no setup; in any other mode they are required.
 */
export function loadEnv(raw: RawEnv): Env {
  const dev = bool(raw.INSIGHT_DEV, false)
  const databaseUrl = str(raw.INSIGHT_DATABASE_URL ?? raw.DATABASE_URL, '')
  if (!databaseUrl) {
    throw new EnvError('INSIGHT_DATABASE_URL is required (connection string for the insight_app role)')
  }

  const keys = {} as Env['keys']
  for (const [name, variable] of Object.entries(KEY_VARS) as [keyof Env['keys'], string][]) {
    keys[name] = resolveKey(raw[variable], variable, name, dev)
  }

  const publicUrl = str(raw.INSIGHT_PUBLIC_URL, 'http://localhost:8789').replace(/\/+$/, '')

  return {
    databaseUrl,
    databaseRole: str(raw.INSIGHT_DB_ROLE, ''),
    publicUrl,
    adminEmailDomains: adminDomains(raw.INSIGHT_ADMIN_EMAIL_DOMAINS, publicUrl),
    offline: bool(raw.INSIGHT_OFFLINE, false),
    dev,
    trustProxy: bool(raw.INSIGHT_TRUST_PROXY, !dev),
    keys,
    mail: {
      driver: enumOf<MailDriver>(raw.INSIGHT_MAIL_DRIVER, ['console', 'resend', 'smtp'], 'console'),
      from: str(raw.INSIGHT_MAIL_FROM, '옆자리 인사이트 <no-reply@yeopjari.bid>'),
      replyTo: str(raw.INSIGHT_MAIL_REPLY_TO, ''),
      resendApiKey: str(raw.RESEND_API_KEY, ''),
      smtpUrl: str(raw.INSIGHT_SMTP_URL, ''),
    },
    yeopjari: {
      url: str(raw.INSIGHT_YEOPJARI_URL, 'https://yeopjari.bid').replace(/\/+$/, ''),
      clientId: str(raw.INSIGHT_YEOPJARI_CLIENT_ID, ''),
      clientSecret: str(raw.INSIGHT_YEOPJARI_CLIENT_SECRET, ''),
    },
    internalKey: str(raw.INSIGHT_INTERNAL_KEY, dev ? 'dev-internal-key' : ''),
    build: {
      version: str(raw.INSIGHT_VERSION, '0.0.0-dev'),
      commit: str(raw.INSIGHT_COMMIT, 'dev'),
      builtAt: str(raw.INSIGHT_BUILT_AT, ''),
      channel: str(raw.INSIGHT_CHANNEL, dev ? 'dev' : 'release'),
    },
  }
}

function resolveKey(value: string | undefined, variable: string, purpose: string, dev: boolean): Uint8Array {
  if (value && value.trim() !== '') {
    let bytes: Uint8Array
    try {
      bytes = fromHex(value)
    } catch {
      throw new EnvError(`${variable} must be 64 hex characters (32 bytes)`)
    }
    if (bytes.length !== 32) {
      throw new EnvError(`${variable} must decode to 32 bytes, got ${bytes.length}`)
    }
    return bytes
  }
  if (!dev) {
    throw new EnvError(
      `${variable} is required. Generate one with: ` +
        `node -e "console.log(require('crypto').randomBytes(32).toString('hex'))"`,
    )
  }
  // Deterministic development key: distinct per purpose, obvious in a dump,
  // and never produced outside dev mode.
  const seed = `insight-development-key-do-not-use-in-production:${purpose}`
  const out = new Uint8Array(32)
  for (let i = 0; i < 32; i++) out[i] = seed.charCodeAt(i % seed.length) ^ (i * 31)
  return out
}

function str(value: string | undefined, fallback: string): string {
  const text = (value ?? '').trim()
  return text === '' ? fallback : text
}

function bool(value: string | undefined, fallback: boolean): boolean {
  const text = (value ?? '').trim().toLowerCase()
  if (['1', 'true', 'yes', 'on'].includes(text)) return true
  if (['0', 'false', 'no', 'off'].includes(text)) return false
  return fallback
}

function enumOf<T extends string>(value: string | undefined, allowed: readonly T[], fallback: T): T {
  const text = (value ?? '').trim().toLowerCase() as T
  return allowed.includes(text) ? text : fallback
}

/**
 * Who may be appointed an administrator, by e-mail domain.
 *
 * Explicit list when given; otherwise the registrable part of the domain the
 * service is published at, so a deployment at insight.yeopjari.bid accepts
 * @yeopjari.bid and nothing else. A localhost address yields no domain at all,
 * which means no extra administrators until one is configured.
 */
function adminDomains(explicit: string | undefined, publicUrl: string): string[] {
  const listed = (explicit ?? '')
    .split(/[,\s]+/)
    .map((d) => d.trim().toLowerCase().replace(/^@/, ''))
    .filter((d) => d.includes('.'))
  if (listed.length > 0) return listed
  try {
    const host = new URL(publicUrl).hostname.toLowerCase()
    const parts = host.split('.')
    return parts.length >= 2 ? [parts.slice(-2).join('.')] : []
  } catch {
    return []
  }
}
